pragma solidity >=0.8.0;
contract Single {
    uint256 public result;
    uint256 public direct;
    function f(uint256 x) public returns (uint256) {
        return x - 200;
    }
    function g(uint256 x) public returns (uint256) {
        uint256 r = this.f(x);
        result = r;
        return r;
    }
    function h(uint256 x) public {
        direct = this.f(x);
    }
}
